'use client';

import { useEffect } from 'react';

// Segment-level recovery: a failed tab must not take down the entire portal.
// Keep errors out of the page (and never display credentials or stack traces).
export default function DashboardError({
  error, reset,
}: {
  error: Error & { digest?: string };
  reset: () => void;
}) {
  useEffect(() => {
    // Digest is a non-sensitive diagnostic identifier generated by Next.js.
    console.error('[dashboard-page] render failed', error.digest || error.name);
  }, [error]);

  return (
    <main role="alert" style={{ maxWidth: 620, margin: 'min(12vh, 90px) auto', padding: '24px 18px', color: 'var(--mc-text-1)' }}>
      <section style={{ background: 'var(--mc-bg-1)', border: '1px solid var(--mc-bg-4)', borderRadius: 14, padding: '24px clamp(18px, 4vw, 32px)' }}>
        <h1 style={{ margin: '0 0 12px', fontSize: 22, fontWeight: 800 }}>This view could not load</h1>
        <p style={{ lineHeight: 1.6, color: 'var(--mc-text-3)', fontSize: 14 }}>
          Your saved watchlists and research have not been deleted. The selected view encountered an error.
          Try loading it again, or return to the dashboard.
        </p>
        <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginTop: 20 }}>
          <button type="button" onClick={reset} style={{ padding: '10px 18px', fontWeight: 750, borderRadius: 8, background: 'var(--mc-accent)', color: '#fff', border: 'none', cursor: 'pointer' }}>
            Retry this view
          </button>
          <a href="/" style={{ padding: '10px 18px', textDecoration: 'none', borderRadius: 8, border: '1px solid var(--mc-bg-4)', color: 'var(--mc-text-1)' }}>
            Dashboard home
          </a>
        </div>
        {error.digest && <p style={{ margin: '18px 0 0', fontSize: 11, color: 'var(--mc-text-4)' }}>Support reference: {error.digest}</p>}
      </section>
    </main>
  );
}
